+    steer(b, dx, dy, speed, dt);
+    b.x += b.vx * dt; b.y += b.vy * dt;
+    const nc = Math.hypot(b.x, b.y);
+    if (nc > R * 0.97) { b.x *= (R * 0.97) / nc; b.y *= (R * 0.97) / nc; }
