  g.fillText('blue →', pad + iw - 38, h - 6); g.fillText('red', 4, 16);
  g.fillText(String(Math.round(maxB)), pad + iw - 14, h - 18);
  g.fillText(String(Math.round(maxR)), 4, 30);
