  }
});

// ---------- main loop ----------
function spawnParticles() {
  for (const ev of world.events) {
    const conf = {
      eat: ['#c6f542', 6], hit: ['#ffb14d', 7],
      birth: [ev.color === 'blue' ? '#7ec8f7' : '#ff9d94', 8],
      death: ['#cfd8c8', 6],
    }[ev.type];
