  drawWorld(ts);
  chartTimer += realDt; summaryTimer += realDt;
  if (chartTimer > 0.35) { chartTimer = 0; drawMainChart(); drawPhase(); drawTraits(); updateInspector(); }
  if (summaryTimer > 3) { summaryTimer = 0; updateSummary(); }
  requestAnimationFrame(frame);
}

buildPresets();
buildControls();
resetWorld();
resize();
setPlaying(true);
requestAnimationFrame(frame);"}

