for (const [name, ov] of Object.entries(PRESETS)) {
  const w = createWorld({ ...DEFAULTS, ...ov });
  const dt = 1 / 30, H = [];
  for (let t = 0; t < 300; t += dt) { stepWorld(w, dt); w.events.length = 0; if (Math.round(t / dt) % 15 === 0) H.push(counts(w)); }
  const B = H.map(h => h.blue), R = H.map(h => h.red);
  // count wave cycles: blue local maxima separated by dips of >=25%
  let waves = 0, peak = 0, dipped = true;
