const page = await browser.getPage("garden-9301");
// click around busy spots until the inspector opens
const spots = [[470,215],[320,295],[265,350],[555,380],[415,250],[335,430],[205,330],[575,290]];
let opened = false;
for (const [x,y] of spots) {
  await page.mouse.click(x, y);
  await new Promise(r => setTimeout(r, 450));
  opened = await page.evaluate(() => !document.getElementById('inspector').classList.contains('hidden'));
  if (opened) break;
}
const insp = opened ? await page.evaluate(() => document.getElementById('inspector').innerText.replace(/\n+/g,' | ')) : 'NOT OPENED';
console.log("inspector:", insp);
// drag to rotate
await page.mouse.move(300, 300); await page.mouse.down();
await page.mouse.move(520, 300, { steps: 12 }); await page.mouse.up();
await new Promise(r => setTimeout(r, 600));
// speed 4x and let history build
await page.evaluate(() => {
  const s = document.getElementById('ctl-simSpeed-top');
  s.value = 4; s.dispatchEvent(new Event('input', { bubbles: true }));
});
console.log("speed:", await page.evaluate(() => document.getElementById('speed-val').textContent));
await new Promise(r => setTimeout(r, 22000));
const after = await page.evaluate(() => ({
  fruit: document.getElementById('st-fruit').textContent,
  blue: document.getElementById('st-blue').textContent,
  red: document.getElementById('st-red').textContent,
  day: document.getElementById('st-time').textContent,
  summary: document.getElementById('summary').textContent,
}));
console.log(JSON.stringify(after));
await page.evaluate(() => window.scrollTo(0, 520));
await new Promise(r => setTimeout(r, 500));
await saveScreenshot(await page.screenshot(), "garden-2.png");
console.log("shot2 saved");
