const page = await browser.getPage("garden-9301");
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
await page.evaluate(() => window.scrollTo(0, 0));
// fruit-rich preset
await page.evaluate(() => [...document.querySelectorAll('.preset')].find(b => b.textContent === 'Fruit-rich garden').click());
await new Promise(r => setTimeout(r, 9000));
const rich = await page.evaluate(() => ({ blue: +document.getElementById('st-blue').textContent, treesFruit: +document.getElementById('st-fruit').textContent }));
// pause freezes counts
await page.click('#btn-play');
const p1 = await page.evaluate(() => document.getElementById('st-time').textContent + '/' + document.getElementById('st-blue').textContent);
await new Promise(r => setTimeout(r, 2500));
const p2 = await page.evaluate(() => document.getElementById('st-time').textContent + '/' + document.getElementById('st-blue').textContent);
// step advances while paused; reset restores
await page.click('#btn-step');
await page.click('#btn-reset');
await new Promise(r => setTimeout(r, 600));
const afterReset = await page.evaluate(() => ({ blue: document.getElementById('st-blue').textContent, red: document.getElementById('st-red').textContent, play: document.getElementById('btn-play').textContent }));
console.log(JSON.stringify({ rich, pausedFrozen: p1 === p2, p1, afterReset, errors }));
await page.click('#btn-play');
await browser.closePage("garden-9301");
console.log("done");
